from collections import Counter

class Solution:
    def customSortString(self, order: str, s: str) -> str:
        count = Counter(s)
        result = []
        for c in order:
            if c in count:
                result.append(c * count[c])
                del count[c]
        for c, cnt in count.items():
            result.append(c * cnt)
        return ''.join(result)

